mapper.select:
SELECT user_id
FROM users
WHERE email = #{email}

SELECT workspace_id
FROM sprints
WHERE sprint_id = #{sprintId}

SELECT ta.task_id, u.user_id, u.nickname, u.profile_file_id, f.file_url AS profile_image_url FROM task_assignees ta JOIN users u ON u.user_id = ta.user_id LEFT JOIN files f ON f.file_id = u.profile_file_id WHERE ta.task_id IN
#{taskId}
ORDER BY ta.task_assignee_id
